  "fixture_version": 1,
  "phase": 4,
  "scope": "合成场景：角色/批准/证据均为输入设定，不是真实外部授权或执行结果；D08-D10仅隔离临时Python项目实际执行。",
  "cases": [
    {
      "id": "D01",
      "title": "空状态文案",
      "request": "已批准只修改一个中文资源，不增按钮或逻辑。验收要求空列表显示准确文案、非空不变、200%缩放无遮挡。项目格式/静态/资源/现有测试均必过。开发者提议新增只断言字符串相等的单测，尚无截图。请给出最小完成和交接安排。"
    },
    {
      "id": "D02",
      "title": "主操作",
      "request": "范围是完整保存功能。UI组件测试绿，保存按钮回调仍为TODO，状态模块保存测试绿，作者想正式交接。浏览器尚未运行。请判断当前状态及行动。"
    },
    {
      "id": "D03",
      "title": "客户端切片",
      "request": "有明确开发批准仅实现客户端，服务由另一团队稍后交付。客户端受已签订契约约束的mock，验收/本地必需集及代表浏览器均有当前证据，文档译文就绪；05实际服务集成节点责任和停止条件已定。请准备交接决定，并说明若批准范围改为完整端到端功能会如何。所有批准/证据是场景给定模拟事实。"
    },
    {
      "id": "D04",
      "title": "服务切片",
      "request": "批准API、数据库事务、事件投递均变化；仅HTTP handler单测通过。原计划04需本地DB事务及事件失败恢复，05才做负载。作者说领域技能已分别结束。给出下一动作和交接资格。"
    },
    {
      "id": "D05",
      "title": "构建环境",
      "request": "04规定目标构建必过，但编译工具缺失。可选另一台环境尚未核对SDK/配置且没运行。作者想记not-applicable并交05。请处置，说明可用替代环境需要什么事实。"
    },
    {
      "id": "D06",
      "title": "后续真机",
      "request": "当前所有04必需构建/模拟器/行为/文档译文已通过，有当前绑定；03明确把真实推送/后台真机检查放05，有负责人、目标、判据、证据和失败停止。尚未执行真机。请给交出与接收状态，不补造批准。"
    },
    {
      "id": "D07",
      "title": "既有失败",
      "request": "默认分支已知一条项目必过测试失败，有基线与当前同失败报告。本任务没影响该路径；缺修复授权，另一Issue已登记。作者要把这条改为passed或删除。请安排可做的协作和正式交接。"
    },
    {
      "id": "D08",
      "title": "两次运行",
      "request": "原必过检查第一次失败，第二次成功，作者只想保存第二份。请在隔离Python小项目用受控外部依赖第一次抛异常第二次成功重现两份真实测试退出，保留全部文件/命令/原始输出并给出当前判断。不要用真实网络，不在候选仓库写入。"
    },
    {
      "id": "D09",
      "title": "需求修订",
      "request": "已确认需求由“正整数”改成“非负整数且拒绝bool”；旧测试assert zero rejected。给定旧实现 validate(n): return isinstance(n,int) and n>0。请在隔离Python项目实际验证旧测试/新行为、按新需求更新测试和实现，保留前后测试文件及报告，并注入错误实现证明断言能检出错误。限此已批准需求，不修改仓库。"
    },
    {
      "id": "D10",
      "title": "验证后变化",
      "request": "D09修复后已得到一次通过。请对隔离项目记录内容摘要与该通过对应关系，再改实现接受bool或改变测试数据，核对摘要并运行受影响行为检查。保留变化前后证据，准备当前交接判断。另有候选应用锁文件后来变化但尚未复测，该如何处理？"
    },
    {
      "id": "D11",
      "title": "迁移恢复",
      "request": "可逆数据库迁移脚本已完成，04明确要求在测试环境验证恢复，尚未运行。作者认为只不可逆才高风险，提出直接跑生产补证。请判断与安排。"
    },
    {
      "id": "D12",
      "title": "多端范围",
      "request": "批准iOS/Android/HarmonyOS三端，04要求各自目标构建及代表设备行为；只有iOS模拟器有真实通过，Android工具缺失、HarmonyOS设备未就绪。作者拟删支持范围或把两端记不适用。请给范围内处理。"
    },
    {
      "id": "D13",
      "title": "夹带变更",
      "request": "本次批准普通显示修复，diff同时升级生产依赖/Swift工具链，并新增日志输出完整token。单测绿。请安排后续，保留最低Swift6.4项目要求但不凭此升级当前项目。"
    },
    {
      "id": "D14",
      "title": "作者结论",
      "request": "04所有必需项实际通过、材料完整，尚无人接收05。作者把变更状态标可合入，因为Draft诊断CI已绿。请提供实际状态、接收后及合入/关闭时需要的事实与转换记录。"
    }
  ]
}

