from pathlib import Path
from dependency import read_external_value

def load_value(fixture_path: Path) -> str:
    return read_external_value(fixture_path)

import unittest
from pathlib import Path
from service import load_value

class LoadTests(unittest.TestCase):
    def test_required_value(self):
        self.assertEqual(load_value(Path("fixture.txt")), "ready")

import unittest
from validation import validate

class ValidationTests(unittest.TestCase):
    def test_nonnegative_integers(self):
        for value in (0, 1, 2, 10**100):
            with self.subTest(value=value):
                self.assertTrue(validate(value))

    def test_other_values_rejected(self):
        for value in (-1, -10**100, True, False, None, 0.0, 1.0, "0", "1", [], {}):
            with self.subTest(value=value):
                self.assertFalse(validate(value))

